// Builds one readable alert from the Error Trigger data.
const e = $('When a workflow fails').first().json;
const s = $('Settings').first().json;
if (!/^https?:\/\//.test(String(s.chatWebhookUrl || ''))) throw new Error('Paste your chat incoming webhook URL into the Settings node.');
const wf = e.workflow || {};
const ex = e.execution || {};
const err = (ex.error || (e.trigger && e.trigger.error) || {});
const msg = String(err.message || err.description || 'Unknown error').split('\n')[0].slice(0, 600);
const env = s.environment ? `[${s.environment}] ` : '';
const lines = [
  `🚨 ${env}n8n workflow failed: ${wf.name || 'unknown workflow'}`,
  ex.lastNodeExecuted ? `Node: ${ex.lastNodeExecuted}` : (e.trigger ? 'Failed in the trigger (workflow did not start)' : null),
  `Error: ${msg}`,
  ex.mode ? `Mode: ${ex.mode}${ex.retryOf ? ' (retry of ' + ex.retryOf + ')' : ''}` : null,
  ex.url ? `Execution: ${ex.url}` : null,
].filter(Boolean);
return [{ json: { text: lines.join('\n'), workflowId: wf.id || null, workflowName: wf.name || null, executionId: ex.id || null, error: msg } }];
